import React, { useState } from 'react';
import { User, MapPin, Search, Filter, FileText, AlertOctagon, Calendar, CreditCard, ChevronRight, Trophy, CheckCircle2 } from 'lucide-react';

const CitizensTab = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState(null);
  const [activeFilter, setActiveFilter] = useState('NONE'); // NONE, REPORTS, PENALTIES, SCHEDULES, SUBSCRIPTIONS

  // Mock Data for the List
  const citizens = [
    { id: 'CZ-8821', name: 'ARJUN MEHTA', area: 'GANDHI_NAGAR', zone: 'ZONE_A', status: 'ACTIVE', code: 'GN-402' },
    { id: 'CZ-4412', name: 'SARA KHAN', area: 'SILICON_VALLEY', zone: 'ZONE_C', status: 'OVERDUE', code: 'SV-109' },
    { id: 'CZ-9003', name: 'VIKRAM SINGH', area: 'OLD_TOWN', zone: 'ZONE_B', status: 'ACTIVE', code: 'OT-221' },
  ];

  // Detailed Mock Data for selected citizen
  const citizenDetails = {
    address: 'Flat 402, Royal Residency, Gandhi Nagar, Hyderabad',
    joined: '12_JAN_2025',
    reports: [
      { id: 'REP-12', type: 'MISSED_PICKUP', date: '20_MAR_2026', status: 'RESOLVED' },
      { id: 'REP-09', type: 'OVERFLOW_BIN', date: '15_MAR_2026', status: 'PENDING' },
    ],
    penalties: [
      { id: 'PNL-04', reason: 'NON_SEGREGATED_WASTE', amount: '₹500', date: '10_MAR_2026' }
    ],
    subscriptions: { plan: 'PREMIUM_MONTHLY', expiry: '01_APR_2026', auto_renew: 'ON' },
    schedule: ['MON_08:00', 'WED_08:00', 'FRI_08:00']
  };

  return (
    <div className="flex h-full gap-6 font-black italic uppercase tracking-tighter select-none overflow-hidden">

      {/* 👤 LEFT PANEL: CITIZEN DIRECTORY */}
      <div className="w-1/3 flex flex-col gap-4">
        <div className="bg-[#47510B] p-4 rounded-3xl border-[4px] border-[#47510B] shadow-[4px_4px_0_0_#A1AED1]">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-white/40" size={18} />
            <input 
              type="text" 
              placeholder="SEARCH_BY_NAME_OR_ID..." 
              className="w-full bg-white/10 border-2 border-white/20 rounded-xl p-3 pl-10 text-white text-xs outline-none focus:border-[#FFF24D] transition-colors"
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>

        <div className="flex-grow overflow-y-auto custom-scrollbar space-y-3 pr-2">
          {citizens.map(c => (
            <div 
              key={c.id}
              onClick={() => { setSelectedCitizen(c); setActiveFilter('NONE'); }}
              className={`p-4 rounded-[24px] border-4 cursor-pointer transition-all ${selectedCitizen?.id === c.id ? 'bg-[#FFF24D] border-[#47510B] translate-x-2 shadow-none' : 'bg-white border-[#47510B] shadow-[4px_4px_0_0_#47510B] hover:translate-x-1'}`}
            >
              <div className="flex justify-between items-start">
                <h3 className="text-xl leading-none">{c.name}</h3>
                <span className={`text-[10px] px-2 py-0.5 rounded ${c.status === 'ACTIVE' ? 'bg-[#CAD23C]' : 'bg-[#AB1717] text-white'}`}>{c.status}</span>
              </div>
              <p className="text-[10px] opacity-40 mt-1">{c.id} // {c.zone}</p>
            </div>
          ))}
        </div>
      </div>

      {/* 🗄️ RIGHT PANEL: DATA DOSSIER */}
      <div className="flex-grow bg-white border-[6px] border-[#47510B] rounded-[48px] shadow-[12px_12px_0_0_#47510B] overflow-hidden flex flex-col">
        {selectedCitizen ? (
          <>
            {/* DOSSIER HEADER */}
            <div className="bg-[#47510B] p-8 text-white flex justify-between items-end">
              <div>
                <p className="text-[#FFF24D] text-xs mb-2">CITIZEN_DOSSIER_v2.0</p>
                <h2 className="text-5xl leading-none">{selectedCitizen.name}</h2>
                <div className="flex gap-4 mt-4 text-[10px] opacity-60">
                  <span className="flex items-center gap-1"><MapPin size={12}/> {selectedCitizen.area}</span>
                  <span className="flex items-center gap-1"><User size={12}/> {selectedCitizen.code}</span>
                </div>
              </div>
              <div className="text-right">
                <p className="text-4xl">{selectedCitizen.zone}</p>
                <p className="text-[10px] opacity-40">CURRENT_ASSIGNMENT</p>
              </div>
            </div>

            {/* FILTER HUD */}
            <div className="bg-[#FDFAD8] border-b-4 border-[#47510B] p-3 flex gap-2 overflow-x-auto no-scrollbar">
              {[
                { id: 'NONE', label: 'PROFILE', icon: <User size={14}/> },
                { id: 'REPORTS', label: 'REPORTS', icon: <FileText size={14}/> },
                { id: 'PENALTIES', label: 'PENALTIES', icon: <AlertOctagon size={14}/> },
                { id: 'SCHEDULES', label: 'SCHEDULES', icon: <Calendar size={14}/> },
                { id: 'SUBSCRIPTIONS', label: 'SUBSCRIPTIONS', icon: <CreditCard size={14}/> }
              ].map(f => (
                <button 
                  key={f.id}
                  onClick={() => setActiveFilter(f.id)}
                  className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black border-2 transition-all whitespace-nowrap ${activeFilter === f.id ? 'bg-[#47510B] text-white border-[#47510B]' : 'bg-white border-[#47510B]/10 hover:border-[#47510B]'}`}
                >
                  {f.icon} {f.label}
                </button>
              ))}
            </div>

            {/* CONTENT ENGINE */}
            <div className="flex-grow p-8 overflow-y-auto custom-scrollbar">
              {activeFilter === 'NONE' && (
                <div className="grid grid-cols-2 gap-8 animate-in fade-in slide-in-from-bottom-4">
                  <div className="space-y-6">
                    <div>
                      <label className="text-[10px] opacity-30">RESIDENTIAL_ADDRESS</label>
                      <p className="text-2xl mt-1">{citizenDetails.address}</p>
                    </div>
                    <div className="grid grid-cols-2 gap-4 pt-4 border-t-2 border-[#47510B]/10">
                      <div>
                        <label className="text-[10px] opacity-30">JOINED_NETWORK</label>
                        <p className="text-xl">{citizenDetails.joined}</p>
                      </div>
                      <div>
                        <label className="text-[10px] opacity-30">RELIABILITY_SCORE</label>
                        <p className="text-xl text-[#CAD23C]">98.2%</p>
                      </div>
                    </div>
                  </div>
                  <div className="bg-[#47510B]/5 rounded-3xl p-6 border-4 border-dashed border-[#47510B]/20 flex flex-col items-center justify-center text-center">
                    <Trophy size={48} className="text-[#47510B] opacity-20 mb-4" />
                    <p className="text-sm">CITIZEN_RANK: GOLD_OPERATOR</p>
                    <p className="text-[10px] opacity-40 mt-2">EARNED 450 POINTS THIS MONTH</p>
                  </div>
                </div>
              )}

              {activeFilter === 'REPORTS' && (
                <div className="space-y-4">
                  {citizenDetails.reports.map(r => (
                    <div key={r.id} className="bg-white border-4 border-[#47510B] p-4 rounded-2xl flex justify-between items-center shadow-[4px_4px_0_0_#47510B]">
                      <div>
                        <h4 className="text-lg">{r.type}</h4>
                        <p className="text-[10px] opacity-40">{r.id} // {r.date}</p>
                      </div>
                      <span className={`px-3 py-1 rounded-lg text-[10px] ${r.status === 'RESOLVED' ? 'bg-[#CAD23C]' : 'bg-[#FFF24D]'}`}>{r.status}</span>
                    </div>
                  ))}
                </div>
              )}

              {activeFilter === 'PENALTY' && (
                <div className="space-y-4">
                  {citizenDetails.penalties.map(p => (
                    <div key={p.id} className="bg-white border-4 border-[#AB1717] p-4 rounded-2xl flex justify-between items-center shadow-[4px_4px_0_0_#AB1717]">
                      <div>
                        <h4 className="text-lg text-[#AB1717]">{p.reason}</h4>
                        <p className="text-[10px] opacity-40">{p.id} // {p.date}</p>
                      </div>
                      <span className="text-2xl font-black text-[#AB1717]">{p.amount}</span>
                    </div>
                  ))}
                </div>
              )}

              {/* Other filters (Schedules, Subscriptions) would follow similar list patterns */}
              {activeFilter === 'SCHEDULES' && (
                 <div className="grid grid-cols-3 gap-4">
                   {citizenDetails.schedule.map(s => (
                     <div key={s} className="bg-[#47510B] text-white p-6 rounded-3xl text-center border-4 border-[#FFF24D]">
                       <Calendar size={20} className="mx-auto mb-2 opacity-40" />
                       <p className="text-lg">{s.split('_')[0]}</p>
                       <p className="text-2xl font-black text-[#FFF24D]">{s.split('_')[1]}</p>
                     </div>
                   ))}
                 </div>
              )}
            </div>
          </>
        ) : (
          <div className="h-full flex flex-col items-center justify-center text-[#47510B]/20">
            <User size={80} strokeWidth={1} />
            <p className="text-2xl mt-4">SELECT_A_CITIZEN_TO_LOAD_DOSSIER</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default CitizensTab;
